/* ============================================
   CARD COMPONENT
   Content card with preview area and title
   ============================================ */

.ds-card {
  /* Layout */
  display: flex;
  flex-direction: column;
  gap: var(--gap-400); /* 12px */

  /* Sizing */
  flex: 1 1 0;
  min-width: 250px;
  height: 268px;

  /* Appearance */
  background: var(--color-bg-container-primary-semi);
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-600); /* 24px */
  padding: var(--padding-500); /* 20px */
  overflow: hidden;
  color: inherit;
  text-decoration: none;

  /* Interaction */
  transition: transform var(--motion-duration-slow) var(--motion-ease-standard), box-shadow var(--motion-duration-slow) var(--motion-ease-standard);
  /* ds-allow(color): transparent resting state of the sanctioned Card
     hover-lift shadow (see design.md — Do's and Don'ts). */
  box-shadow: 0 0 0 rgba(0, 0, 0, 0);
}

.ds-card--interactive {
  cursor: pointer;
}

.ds-card--interactive:hover {
  transform: translateY(-4px);
  /* ds-allow(color): the sanctioned Card hover-lift shadow — deliberately
     heavier than --shadow-floating (see design.md — Do's and Don'ts). */
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

/* ============================================
   PREVIEW AREA
   ============================================ */

.ds-card__preview {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 184px;
  min-height: 0;
}

/* ============================================
   TITLE
   ============================================ */

.ds-card__title {
  font-family: var(--font-paragraph-family);
  font-family: var(--font-heading-3-family);
  font-size: var(--font-heading-3-size);
  font-weight: var(--font-heading-3-weight);
  line-height: var(--font-heading-3-line-height);
  letter-spacing: var(--font-heading-3-letter-spacing);
  color: var(--color-text-primary);
  width: 100%;
  text-align: center;
}

/* ============================================
   CASE-STUDY VARIANT
   ============================================ */

.ds-card--case-study {
  height: auto;
  min-width: 0;
  /* The cover is inset, not full-bleed: 12px of card around a 12px-radius
     cover keeps the corners concentric with the card's 24px shell. */
  padding: var(--padding-300);
  gap: 0;
  overflow: hidden;
  cursor: pointer;
}

.ds-card--case-study:hover {
  transform: translateY(-4px);
  /* ds-allow(color): same sanctioned hover-lift shadow as the interactive
     variant. */
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

.ds-card--case-study--placeholder {
  opacity: 0.55;
  cursor: default;
}

.ds-card--case-study--placeholder:hover {
  transform: none;
  box-shadow: none;
}

.ds-card--case-study__cover-wrap {
  width: 100%;
  aspect-ratio: 940 / 480;
  overflow: hidden;
  border-radius: var(--radius-300);
  background: var(--color-bg-container-secondary);
}

/* A drawn cover (the `cover` prop) fills the same slot the image would, so a
   grid of cards keeps one cover shape whichever kind it was given. */
.ds-card--case-study__cover-slot,
.ds-card--case-study__cover-slot > * {
  display: block;
  width: 100%;
  height: 100%;
}

.ds-card--case-study__cover-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.ds-card--case-study__cover-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--color-bg-container-secondary);
}

.ds-card--case-study__cover-placeholder-logo {
  width: 64px;
  height: 64px;
  object-fit: contain;
  opacity: 0.6;
}

.ds-card--case-study__body {
  display: flex;
  flex-direction: column;
  gap: var(--gap-200);
  /* 8px on top of the card's 12px inset: text lands 20px from the card edge
     (the old full-bleed body padding) and sits slightly inside the cover. */
  padding: var(--padding-400) var(--padding-200) var(--padding-300);
}

.ds-card--case-study__eyebrow {
  display: flex;
  align-items: center;
  gap: var(--gap-100);
}

.ds-card--case-study__company-logo {
  width: 20px;
  height: 20px;
  object-fit: contain;
  flex-shrink: 0;
}

.ds-card--case-study__company-name {
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-secondary);
}

.ds-card--case-study__title {
  font-size: var(--font-heading-3-size);
  font-weight: var(--font-heading-3-weight);
  line-height: var(--font-heading-3-line-height);
  letter-spacing: var(--font-heading-3-letter-spacing);
  color: var(--color-text-primary);
  margin: 0;
  text-align: left;
}

.ds-card--case-study__dek {
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  color: var(--color-text-secondary);
  margin: 0;
}

'use client';

import React from 'react';
import './Card.css';
import '../../fonts/material-symbols.css';

/** Props owned by Card itself — everything else falls through to the DOM node. */
type CardOwnProps = {
  /** Card variant */
  variant?: 'default' | 'case-study';
  /**
   * Card title displayed below the preview.
   * Note: this shadows the native `title` tooltip attribute, which Card does not expose.
   */
  title: string;
  /** Preview content rendered inside the card (default variant only) */
  children?: React.ReactNode;
  /** Whether the card is interactive (hoverable) */
  interactive?: boolean;
  /** Additional CSS classes */
  className?: string;

  // ── Case-study variant props ──────────────────────────────────────────────
  /** Navigation href — renders the card as an <a> tag */
  href?: string;
  /** Cover image src */
  coverSrc?: string;
  /**
   * Cover content rendered in place of the image — for a cover that is drawn
   * rather than photographed (an SVG, a chart, a live preview). Takes
   * precedence over `coverSrc`, and fills the same fixed-ratio slot.
   */
  cover?: React.ReactNode;
  /** Cover image alt text */
  coverAlt?: string;
  /** Path to the company logo shown in the eyebrow */
  companyLogo?: string;
  /** Company name shown in the eyebrow */
  companyName?: string;
  /** Subtitle / dek line below the title */
  dek?: string;
  /** Render as a disabled placeholder (no href, dimmed, not interactive) */
  placeholder?: boolean;
};

export interface CardProps
  extends CardOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof CardOwnProps> {}

/**
 * Card renders a preview tile, or a case-study tile when `variant="case-study"`.
 *
 * Renders a `<div>`, or an `<a>` in the case-study variant when `href` is
 * supplied. Forwards a ref to whichever element it renders and spreads
 * unrecognised props onto it.
 */
export const Card = React.forwardRef<HTMLDivElement | HTMLAnchorElement, CardProps>(
  (
    {
      variant = 'default',
      title,
      children,
      interactive = false,
      onClick,
      onKeyDown,
      className = '',
      href,
      coverSrc,
      cover,
      coverAlt,
      companyLogo,
      companyName,
      dek,
      placeholder = false,
      ...rest
    },
    ref,
  ) => {
    // ── Case-study variant ────────────────────────────────────────────────────
    if (variant === 'case-study') {
      const inner = (
        <>
          <div className="ds-card--case-study__cover-wrap">
            {cover ? (
              <div className="ds-card--case-study__cover-slot">{cover}</div>
            ) : coverSrc ? (
              <img
                src={coverSrc}
                alt={coverAlt ?? `${title} cover`}
                className="ds-card--case-study__cover-image"
              />
            ) : (
              <div className="ds-card--case-study__cover-placeholder">
                {companyLogo && (
                  <img
                    src={companyLogo}
                    alt=""
                    className="ds-card--case-study__cover-placeholder-logo"
                  />
                )}
              </div>
            )}
          </div>
          <div className="ds-card--case-study__body">
            {(companyLogo || companyName) && (
              <div className="ds-card--case-study__eyebrow">
                {companyLogo && (
                  <img src={companyLogo} alt="" className="ds-card--case-study__company-logo" />
                )}
                {companyName && (
                  <span className="ds-card--case-study__company-name">{companyName}</span>
                )}
              </div>
            )}
            <h3 className="ds-card--case-study__title">{title}</h3>
            {dek && <p className="ds-card--case-study__dek">{dek}</p>}
          </div>
        </>
      );

      const classes = [
        'ds-card',
        'ds-card--case-study',
        placeholder ? 'ds-card--case-study--placeholder' : '',
        className,
      ]
        .filter(Boolean)
        .join(' ');

      if (placeholder || !href) {
        return (
          <div
            {...rest}
            ref={ref as React.Ref<HTMLDivElement>}
            className={classes}
            aria-disabled="true"
          >
            {inner}
          </div>
        );
      }

      return (
        <a
          {...(rest as React.ComponentPropsWithoutRef<'a'>)}
          ref={ref as React.Ref<HTMLAnchorElement>}
          href={href}
          className={classes}
          onClick={onClick as unknown as React.MouseEventHandler<HTMLAnchorElement>}
        >
          {inner}
        </a>
      );
    }

    // ── Default variant ───────────────────────────────────────────────────────
    const baseClass = 'ds-card';
    const classes = [baseClass, interactive ? `${baseClass}--interactive` : '', className]
      .filter(Boolean)
      .join(' ');

    const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
      onKeyDown?.(e);
      if (!interactive) return;
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        onClick?.(e as unknown as React.MouseEvent<HTMLDivElement>);
      }
    };

    return (
      <div
        {...rest}
        ref={ref as React.Ref<HTMLDivElement>}
        className={classes}
        onClick={interactive ? onClick : undefined}
        onKeyDown={handleKeyDown}
        role={interactive ? 'button' : undefined}
        tabIndex={interactive ? 0 : undefined}
        aria-label={interactive ? title : undefined}
      >
        <div className={`${baseClass}__preview`}>{children}</div>
        <h3 className={`${baseClass}__title`}>{title}</h3>
      </div>
    );
  },
);

Card.displayName = 'Card';
